from __future__ import annotations

import json
from pathlib import Path
from zoneinfo import ZoneInfo

import pandas as pd


DATA_DIR = Path("/app/dataset")
UTC_START = pd.Timestamp("2024-03-15 00:00:00", tz="UTC")
UTC_END = pd.Timestamp("2024-03-16 00:00:00", tz="UTC")

COMPLETED_MAINTENANCE = {
    "FARM_C": [
        (pd.Timestamp("2024-03-16 08:00:00"), pd.Timestamp("2024-03-16 12:00:00")),
    ],
    "FARM_F": [
        (pd.Timestamp("2024-03-15 12:00:00"), pd.Timestamp("2024-03-15 14:00:00")),
    ],
}


def _detect_encoding(path: Path) -> str:
    prefix = path.read_bytes()[:4]
    if prefix.startswith((b"\xff\xfe", b"\xfe\xff")):
        return "utf-16"
    if prefix.startswith(b"\xef\xbb\xbf"):
        return "utf-8-sig"
    return "utf-8"


def _read_production_csv(path: Path) -> pd.DataFrame:
    encoding = _detect_encoding(path)
    with path.open("r", encoding=encoding, newline="") as f:
        for _ in range(3):
            f.readline()
        header = f.readline()

    sep = ";" if header.count(";") > header.count(",") else ","
    return pd.read_csv(path, skiprows=3, encoding=encoding, sep=sep, dtype=str, engine="python")


def _parse_number(series: pd.Series) -> pd.Series:
    text = series.astype("string").str.strip().str.replace("\x00", "", regex=False)
    comma_decimal = text.str.contains(",", regex=False, na=False)
    normalized = text.copy()
    normalized.loc[comma_decimal] = (
        normalized.loc[comma_decimal]
        .str.replace(".", "", regex=False)
        .str.replace(",", ".", regex=False)
    )
    return pd.to_numeric(normalized, errors="coerce")


def _parse_timestamp(series: pd.Series) -> pd.Series:
    text = series.astype("string").str.strip().str.replace("\x00", "", regex=False)
    iso = pd.to_datetime(text, format="%Y-%m-%d %H:%M:%S", errors="coerce")
    dotted = pd.to_datetime(text, format="%d.%m.%Y %H:%M:%S", errors="coerce")
    return iso.fillna(dotted)


def _unit_to_kwh_factor(unit: str) -> float:
    normalized = unit.lower()
    if normalized == "kwh":
        return 1.0
    if normalized == "mwh":
        return 1000.0
    if normalized == "wh":
        return 0.001
    if normalized == "btu":
        return 0.0002930710701722222
    if normalized == "kw":
        return 1.0
    raise ValueError(f"Unsupported unit: {unit}")


def _timestamp_col(df: pd.DataFrame) -> str:
    return next(col for col in df.columns if col.strip() == "timestamp")


def _inverter_temp_col(df: pd.DataFrame) -> str:
    return next(col for col in df.columns if col.strip() == "inverter_temperature_C")


def _value_col(df: pd.DataFrame, configured_name: str) -> str:
    if configured_name in df.columns:
        return configured_name
    return next(col for col in df.columns if col.strip() == configured_name.strip())


def _sample_cadence_hours(df: pd.DataFrame, timestamp_col: str) -> float:
    timestamps = _parse_timestamp(df[timestamp_col]).dropna().sort_values().drop_duplicates()
    diffs = timestamps.diff().dropna()
    diffs = diffs[diffs > pd.Timedelta(0)]
    if diffs.empty:
        return 0.0
    return diffs.mode().iloc[0].total_seconds() / 3600.0


def _load_farm_metadata() -> pd.DataFrame:
    registry = pd.read_csv(DATA_DIR / "farm_registry.csv")
    farms = pd.read_csv(DATA_DIR / "farms.csv")
    farms["farm_name_norm"] = farms["farm_name"].str.strip().str.lower()
    return registry.merge(farms, left_on="farm_name", right_on="farm_name_norm", how="inner")


def _load_calibration() -> dict:
    with (DATA_DIR / "sensors_calibration.json").open() as f:
        config = json.load(f)
    return config["enterprise_platform"]["deployment_environments"]["system_config"]["farms"]


def _exclude_shutdown_following_spikes(work: pd.DataFrame) -> pd.DataFrame:
    spike_times = work.loc[work["temp"] > 85.0, "ts_utc"]
    if spike_times.empty:
        return work

    shutdown = pd.Series(False, index=work.index)
    for spike_time in spike_times:
        shutdown |= (work["ts_utc"] > spike_time) & (
            work["ts_utc"] <= spike_time + pd.Timedelta(minutes=45)
        )
    return work.loc[~shutdown]


def _exclude_completed_maintenance(work: pd.DataFrame, farm_id: str) -> pd.DataFrame:
    if farm_id not in COMPLETED_MAINTENANCE:
        return work

    maintenance = pd.Series(False, index=work.index)
    for start, end in COMPLETED_MAINTENANCE[farm_id]:
        maintenance |= (work["ts_local"] >= start) & (work["ts_local"] < end)
    return work.loc[~maintenance]


def answer() -> dict[str, int]:
    calibration = _load_calibration()
    farm_metadata = _load_farm_metadata()
    totals: dict[str, int] = {}

    for row in farm_metadata.itertuples(index=False):
        farm_id = row.farm_id
        sensor_config = calibration[farm_id]
        calibration_data = sensor_config["calibration_data"]
        sensor_info = sensor_config["sensor_info"]

        df = _read_production_csv(DATA_DIR / f"production_{farm_id}.csv")
        df = df.drop_duplicates()

        timestamp_col = _timestamp_col(df)
        # Export retries put an erroneous reading before the replacement at the same timestamp.
        df = df.drop_duplicates(subset=[timestamp_col], keep="last")

        value_col = _value_col(df, calibration_data["value_column_name"])
        temp_col = _inverter_temp_col(df)
        cadence_hours = _sample_cadence_hours(df, timestamp_col)

        ts_local = _parse_timestamp(df[timestamp_col])
        true_values = _parse_number(df[value_col]) - float(calibration_data["calibration_offset"])
        temperatures = _parse_number(df[temp_col])

        work = pd.DataFrame(
            {
                "ts_local": ts_local,
                "value": true_values,
                "temp": temperatures,
            }
        )
        work = work.loc[work["ts_local"].notna() & work["value"].notna()]

        localized = work["ts_local"].dt.tz_localize(
            ZoneInfo(row.timezone), ambiguous="NaT", nonexistent="NaT"
        )
        work = work.assign(ts_utc=localized.dt.tz_convert("UTC"))
        work = work.loc[work["ts_utc"].notna()]

        work = _exclude_shutdown_following_spikes(work)
        work = work.loc[(work["ts_utc"] >= UTC_START) & (work["ts_utc"] < UTC_END)]
        work = _exclude_completed_maintenance(work, farm_id)

        work = work.loc[work["value"] >= 0]
        if work.empty:
            totals[farm_id] = 0
            continue

        factor = _unit_to_kwh_factor(sensor_info["unit"])
        if sensor_info["reading_type"].lower() == "power":
            total = (work["value"] * factor * cadence_hours).sum()
        else:
            total = (work["value"] * factor).sum()

        totals[farm_id] = round(float(total))

    return totals


if __name__ == "__main__":
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)

